import { useMemo } from 'react';
import { useIntl } from 'react-intl';

import { overviewCardIdToPresetKpiValue } from '../../../utils/kpiPreset';
import {
  PERFORMANCE_AND_BREAKDOWN_EMPTY_DESCRIPTION_I18N_ID,
  PERFORMANCE_AND_BREAKDOWN_EMPTY_TITLE_I18N_ID,
  PERFORMANCE_AND_BREAKDOWN_ERROR_DESCRIPTION_I18N_ID,
  PERFORMANCE_AND_BREAKDOWN_ERROR_TITLE_I18N_ID,
  PERFORMANCE_AND_BREAKDOWN_KPI_MEASURE_SLUG,
  PERFORMANCE_AND_BREAKDOWN_MEASURE_I18N_ID,
} from '../constants';
import type { PerformanceAndBreakdownViewState } from '../types';

function kpiSubFilterSlug(kpi: string | undefined): string {
  if (!kpi || kpi === 'undefined') return 'volume';
  return overviewCardIdToPresetKpiValue(kpi).replaceAll('_', '-');
}

export function usePerformanceAndBreakdownSectionUi(
  kpi: string | undefined,
  view: PerformanceAndBreakdownViewState,
) {
  const { formatMessage } = useIntl();

  const measure = useMemo(() => {
    const kpiSlug = kpiSubFilterSlug(kpi);
    const measureId =
      PERFORMANCE_AND_BREAKDOWN_MEASURE_I18N_ID[kpiSlug] ??
      PERFORMANCE_AND_BREAKDOWN_MEASURE_I18N_ID[
        PERFORMANCE_AND_BREAKDOWN_KPI_MEASURE_SLUG.VOLUME
      ];
    return formatMessage({ id: measureId });
  }, [formatMessage, kpi]);

  const stateMessage = useMemo(() => {
    if (view === 'error') {
      return {
        title: formatMessage({
          id: PERFORMANCE_AND_BREAKDOWN_ERROR_TITLE_I18N_ID,
        }),
        description: formatMessage({
          id: PERFORMANCE_AND_BREAKDOWN_ERROR_DESCRIPTION_I18N_ID,
        }),
      };
    }
    if (view === 'empty') {
      return {
        title: formatMessage({
          id: PERFORMANCE_AND_BREAKDOWN_EMPTY_TITLE_I18N_ID,
        }),
        description: formatMessage({
          id: PERFORMANCE_AND_BREAKDOWN_EMPTY_DESCRIPTION_I18N_ID,
        }),
      };
    }
    return undefined;
  }, [formatMessage, view]);

  return { measure, stateMessage };
}
